
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"GrandXAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
	
		    var tmpMess=k.data.split("#");

			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.xyu.rbe!=undefined){
			
			if(gameController.ehm!=parseInt(tmpMess[1])){
				
			gameController.wlc=parseInt(tmpMess[1]);	
			gameController.ehm=parseInt(tmpMess[1]);	
			gameController.xyu.rbe.mmk("creditd", "#pen", [gameController.cec(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
